INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(51611, 'Jeremiah 50:18', 'Jeremiah', 50, 18, 'نو په دې وجه مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، زۀ به اوس د بابل بادشاه او د هغۀ مُلک له سزا ورکړم لکه څنګه چې ما د اسور بادشاه له ورکړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_18.mp3', '', 1761754199, 1761754199),
(51612, 'Jeremiah 50:19', 'Jeremiah', 50, 19, 'زۀ به بنى اِسرائيل خپل د څرن ځائ ته واپس راولم او هغوئ به د کرمل او بسن په پټو کښې وڅريږى، او د هغوئ لوږه به د اِفرائيم او د جِلعاد په غونډو کښې معموره شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_19.mp3', '', 1761754199, 1761754199),
(51613, 'Jeremiah 50:20', 'Jeremiah', 50, 20, 'په هغه ورځو کښې، مالِک خُدائ فرمائى چې، د اِسرائيل ګناهونه به ولټولے شى خو يو به په کښې پېدا نۀ شى، او د يهوداه ګناهونه به ولټولے شى او هيڅ ګناه به په کښې پېدا نۀ شى، ځکه چې کوم ما ژوندى پرېښودى دى زۀ به د هغوئ ګناهونه معاف کړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_20.mp3', '', 1761754199, 1761754199),
(51614, 'Jeremiah 50:21', 'Jeremiah', 50, 21, 'مالِک خُدائ فرمائى، ”زما لښکرو د مراتايم په وطن او د فقود په خلقو باندې حمله وکړئ. هغوئ پسې شئ، او وې وژنئ او مکمل يې تباه کړئ، او هر څۀ وکړئ د څۀ چې ما حکم درکړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_21.mp3', '', 1761754199, 1761754199),
(51615, 'Jeremiah 50:22', 'Jeremiah', 50, 22, 'په مُلک کښې دې د جنګ شور او ژړاګانې واورېدلے شى، او د لوئې تباهۍ آوازونه اورېدلے کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_22.mp3', '', 1761754199, 1761754199),
(51616, 'Jeremiah 50:23', 'Jeremiah', 50, 23, 'په ټوله دُنيا کښې د بابل لوئ او زورَور څټک څنګه ټوکړې ټوکړې شو. او وګورئ چې بابل څنګه په نورو قومونو کښې د وحشت مثال وګرځېدو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_23.mp3', '', 1761754199, 1761754199),
(51617, 'Jeremiah 50:24', 'Jeremiah', 50, 24, 'اے بابليانو، ما تاسو ته لټ کېښودلو، خو تاسو پرې خبر نۀ وئ خو په کښې ګرفتار شوئ، ځکه چې تاسو د مالِک خُدائ خلاف جنګ وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_24.mp3', '', 1761754199, 1761754199),
(51618, 'Jeremiah 50:25', 'Jeremiah', 50, 25, 'مالِک خُدائ خپل د وسلې ګودام کولاو کړے دے او د خپل غضب وسله يې ترې راويستلې ده، ځکه چې مالِک خُدائ ربُ الافواج به دا د بابل خلاف د هغوئ په مُلک کښې استعمال کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_25.mp3', '', 1761754199, 1761754199),
(51619, 'Jeremiah 50:26', 'Jeremiah', 50, 26, 'د هرې خوا نه د هغۀ خلاف حمله وکړئ، او ګودامونه يې مات کړئ، او هغه لکه د غلې دانو په شان ډېرے کړئ. په مکمل توګه هغه تباه کړئ او هيڅ څوک په کښې ژوندى مۀ پرېږدئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_26.mp3', '', 1761754199, 1761754199),
(51620, 'Jeremiah 50:27', 'Jeremiah', 50, 27, 'د هغوئ ټول غوَيان حلال کړئ، په دوئ دې افسوس وى ځکه د هغوئ د سزا او حساب ورځ او وخت رارسېدلے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_27.mp3', '', 1761754199, 1761754199),
(51621, 'Jeremiah 50:28', 'Jeremiah', 50, 28, 'هغه کسانو ته غوږ شئ څوک چې د بابل نه راتښتېدلى دى، نو هغوئ په يروشلم کښې وائى چې مالِک خُدائ زمونږ خُدائ پاک د هغوئ نه څنګه انتقام اخلى څوک چې د هغۀ کور تباه کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_28.mp3', '', 1761754199, 1761754199),
(51622, 'Jeremiah 50:29', 'Jeremiah', 50, 29, 'ټول لينده چلوونکى د بابل خلاف راجمع کړئ، محاصره يې کړئ چې يو کس هم درنه ونۀ تښتى. هغۀ ته د خپلو اعمالو په مطابق بدله ورکړئ، هغۀ سره هغه څۀ وکړئ کوم چې دۀ د نورو خلقو سره کړى دى. ځکه چې بابل د خپلې مغرورتيا په وجه د مالِک خُدائ د بنى اِسرائيلو د مقدس ذات خلاف سرکشى کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_29.mp3', '', 1761754199, 1761754199),
(51623, 'Jeremiah 50:30', 'Jeremiah', 50, 30, 'مالِک خُدائ فرمائى چې، د هغۀ ځوانان به په کوڅو کښې راپرېوځى او قتل به شى، او د هغوئ فوجيان به په هغه ورځ ټول ختم کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_30.mp3', '', 1761754199, 1761754199),
(51624, 'Jeremiah 50:31', 'Jeremiah', 50, 31, 'مالِک خُدائ ربُ الافواج فرمائى چې، ګورئ، زۀ ستاسو خلاف يم، اے مغروره خلقو، ستاسو د سزا ورځ رارسېدلې ده هغه وخت چې زۀ تاسو له سزا درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_31.mp3', '', 1761754199, 1761754199),
(51625, 'Jeremiah 50:32', 'Jeremiah', 50, 32, 'ستا کبرژن قوم به تيندک وخورى او راوبه غورزيږى، او هيڅ څوک به تاسو نۀ راوچتوى، زۀ به د هغۀ په ښارونو اور بل کړم او هغه به په خپل شا او خوا کښې ځان سره هر څۀ وسوزوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_32.mp3', '', 1761754199, 1761754199),
(51626, 'Jeremiah 50:33', 'Jeremiah', 50, 33, 'مالِک خُدائ ربُ الافواج فرمائى چې، د اِسرائيل او د يهوداه خلق مظلومان دى، هغوئ چې چا نيولى دى نو د هغوئ د پرېښودو نه اِنکار کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_33.mp3', '', 1761754199, 1761754199),
(51627, 'Jeremiah 50:34', 'Jeremiah', 50, 34, 'خو د هغوئ بچ کوونکے ډېر زورَور دے، او مالِک خُدائ ربُ الافواج د هغۀ نوم دے. هغه به په سختۍ سره د هغوئ د مسئلې دفاع وکړى، او هغه به دوئ ته آرام ورکړى، خو د بابل خلق به نا آرامه کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_34.mp3', '', 1761754199, 1761754199),
(51628, 'Jeremiah 50:35', 'Jeremiah', 50, 35, 'مالِک خُدائ فرمائى چې، د تباهۍ تُوره دې بابل تباه کړى. هغه دې د بابل ټول اوسېدونکى او د هغۀ آفسران او هوښياران خلق تباه کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_35.mp3', '', 1761754199, 1761754199),
(51629, 'Jeremiah 50:36', 'Jeremiah', 50, 36, 'د هغوئ دروغژن نبيان به په جنګ کښې مړۀ شى، او هغوئ به بې‌وقوفان ثابت شى. د هغوئ تکړه فوجيان به په جنګ کښې قتل کړے شى، او هغوئ به سختو يرو ترخو کښې راګېر شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_36.mp3', '', 1761754199, 1761754199),
(51630, 'Jeremiah 50:37', 'Jeremiah', 50, 37, 'جنګ به د هغوئ خلاف د هغوئ آسونه او جنګى ګاډۍ تباه کړى او په هغۀ کښې د نورو مُلکونو فوجيان به هم تباه کړى. او هغوئ به د ښځو په شان بُزدله شى. او جنګ به د هغوئ خزانې تباه کړى، او لوټ به يې کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_37.mp3', '', 1761754199, 1761754199),
(51631, 'Jeremiah 50:38', 'Jeremiah', 50, 38, 'د هغۀ د اوبو ذخيرې دې اوچې کړے شى. هغه به اوچې شى، ځکه چې ټول مُلک د بُتانو نه ډک شوے دے، او د هغه خلقو د بُتانو د يرې نه لکه د ليونو په شان عمل وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_38.mp3', '', 1761754199, 1761754199),
(51632, 'Jeremiah 50:39', 'Jeremiah', 50, 39, 'نو بيا به په بابل کښې د دشتو ځناور اوسيږى، او د ګيدړانو او ګونګيانو په کور به بدل شى. نو دا به بيا هيڅکله آباد نۀ شى او دا به همېشه دپاره شاړ پروت وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_39.mp3', '', 1761754199, 1761754199),
(51633, 'Jeremiah 50:40', 'Jeremiah', 50, 40, 'لکه څنګه چې خُدائ پاک سدوم او عموره، سره د ګاونډيانو تباه کړل هم هغه شان به بابل هم تباه کړى. مالِک خُدائ فرمائى چې، نو هيڅ څوک به هلته نۀ اوسيږى او نۀ به يو انسان په کښې ژوند کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_40.mp3', '', 1761754199, 1761754199),
(51634, 'Jeremiah 50:41', 'Jeremiah', 50, 41, 'وګورئ، د شمال د خوا نه فوج راروان دے، يو لوئ قوم او ډېر بادشاهان د دُنيا د آخر نه راپاڅېدلى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_41.mp3', '', 1761754199, 1761754199),
(51635, 'Jeremiah 50:42', 'Jeremiah', 50, 42, 'هغوئ په ليندو او نېزو باندې سمبال دى، او هغوئ ظالمان دى او هيڅ رحم په کښې نشته. کله چې هغوئ په خپلو آسونو باندې سوارۀ شى لکه د سمندر داسې غړمبار کوى، هغوئ جنګ ته په قطارونو کښې راروان دى چې په لور بابل باندې حمله وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_42.mp3', '', 1761754199, 1761754199),
(51636, 'Jeremiah 50:43', 'Jeremiah', 50, 43, 'د بابل بادشاه چې د دشمن د راتلو په حقله دا خبر واورېدو، نو د هغۀ لاسونه شل شول. هغه يرې او دردونو ونيولو، داسې درد لکه چې د ښځې د لنګون په وخت کښې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_43.mp3', '', 1761754199, 1761754199),
(51637, 'Jeremiah 50:44', 'Jeremiah', 50, 44, 'لکه څنګه چې يو زمرے د اُردن د جاړو بوټو نه د څرن زمکې ته راځى او په ګډو ورټوپ کوى، نو دغه شان به زۀ د بابل خلق د خپل مُلک نه وشړم، او زۀ به د خپلې خوښى مشر په کښې مقرر کړم. نو هغه به په دوئ حکومت وکړى. څوک زما په شان کېدلے شى؟ او يو مشر به هم زما خلاف ونۀ دريږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_44.mp3', '', 1761754199, 1761754199),
(51638, 'Jeremiah 50:45', 'Jeremiah', 50, 45, 'نو بيا هغې منصوبې ته غوږ شه کومه چې مالِک خُدائ د بابليانو خلاف جوړه کړې ده، تر دې چې واړۀ ماشومان به د ګډورو په شان وشړلے شى، او د هغوئ د څرن ځايونه به وران کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_45.mp3', '', 1761754199, 1761754199),
(51639, 'Jeremiah 50:46', 'Jeremiah', 50, 46, 'زمکه به په دې چغو سورو سره په لړزان شى ”بابل قبضه کړے شوے دے.“ او د هغوئ د مايوسۍ ژړا به په ټوله دُنيا کښې واورېدلے شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah50_verse_46.mp3', '', 1761754199, 1761754199),
(51640, 'Proverbs 31:1', 'Proverbs', 31, 1, 'دا د لموییل پاچا خبرې دي چې مور یې ورته زده کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_1.mp3', '', 1761754199, 1761754199),
(51641, 'Proverbs 31:2', 'Proverbs', 31, 2, '«ای زما زویه! ای زما د ګېډې نه پیدا شویه زویه چې په نذرونو مې لاسته راوړی یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_2.mp3', '', 1761754199, 1761754199),
(51642, 'Proverbs 31:3', 'Proverbs', 31, 3, 'د ځوانۍ قوت دې په ښځو باندې مه ختموه او په هغو لارو تګ مه کوه چې پاچاهان تباه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_3.mp3', '', 1761754199, 1761754199),
(51643, 'Proverbs 31:4', 'Proverbs', 31, 4, 'نو ای لموییله! پاچاهانو ته دا په کار نه وي شراب څښل د پاچاهانو سره ښه نه ښکاري او د نشې شوق د واکدارانو سره مناسب نه وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_4.mp3', '', 1761754199, 1761754199),
(51644, 'Proverbs 31:5', 'Proverbs', 31, 5, 'هسې نه چې هغوی شراب وڅښي او حکمونه هېر کړي او ټول مظلومان له خپل حق نه محروم کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_5.mp3', '', 1761754199, 1761754199),
(51645, 'Proverbs 31:6', 'Proverbs', 31, 6, 'نشه هغه چاته ورکړه چې د مرګ په انتظار وي او شراب هغه چاته ورکړه چې په غم اخته وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_6.mp3', '', 1761754199, 1761754199),
(51646, 'Proverbs 31:7', 'Proverbs', 31, 7, 'پرېږده چې هغوی وڅښي او خپله غریبي هېره کړي او بیا خپل دردونه په یاد رانه وړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_7.mp3', '', 1761754199, 1761754199),
(51647, 'Proverbs 31:8', 'Proverbs', 31, 8, 'د هغوی په ځای خبرې کوه چې د ځان دپاره څه نه شي ویلی او د هغو غریبانو د حق دپاره چې د ګور په غاړه ولاړ دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_8.mp3', '', 1761754199, 1761754199),
(51648, 'Proverbs 31:9', 'Proverbs', 31, 9, 'خپله خوله خلاصه کړه او په انصاف قضاوت کوه او د خوارانو او مسکینانو د حق ساتنه کوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_9.mp3', '', 1761754199, 1761754199),
(51649, 'Proverbs 31:10', 'Proverbs', 31, 10, 'یوه مېړنۍ او پتمنه ښځه څوک پیدا کولای شي؟ هغه د لعلونو نه ډېره ارزښتناکه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_10.mp3', '', 1761754199, 1761754199),
(51650, 'Proverbs 31:11', 'Proverbs', 31, 11, 'مېړه یې په هغې پوره باور لري او نه پرېږدي چې خاوند یې د څه شي محتاجه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_11.mp3', '', 1761754199, 1761754199),
(51651, 'Proverbs 31:12', 'Proverbs', 31, 12, 'هغه په ټول ژوند کې د خپل مېړه سره ښه کوي او هېڅکله ورته تاوان نه رسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_12.mp3', '', 1761754199, 1761754199),
(51652, 'Proverbs 31:13', 'Proverbs', 31, 13, 'هغه وړۍ او مالوچ پیدا کوي او په خوشحالۍ سره یې په خپلو لاسونو اوبي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_13.mp3', '', 1761754199, 1761754199),
(51653, 'Proverbs 31:14', 'Proverbs', 31, 14, 'هغه د سوداګرانو د کشتۍ‌ګانو په شان وي چې خپل خواړه له لېرې ځای نه راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_14.mp3', '', 1761754199, 1761754199),
(51654, 'Proverbs 31:15', 'Proverbs', 31, 15, 'هغه سهار وختي په تیاره کې له خوبه راپاڅیږي او خپلې کورنۍ ته خواړه برابروي او وینځو ته د کارونو لارښوونه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_15.mp3', '', 1761754199, 1761754199),
(51655, 'Proverbs 31:16', 'Proverbs', 31, 16, 'هغه د ډېر فکر کولو نه وروسته ځمکه اخلي او د خپلې ګټې په پیسو باندې د انګورو باغ جوړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_16.mp3', '', 1761754199, 1761754199),
(51656, 'Proverbs 31:17', 'Proverbs', 31, 17, 'هغه خپله ملا ټینګه تړي او خپلې مټې رانغاړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_17.mp3', '', 1761754199, 1761754199),
(51657, 'Proverbs 31:18', 'Proverbs', 31, 18, 'هغه پوهیږي چې سوداګري یې ګټوره ده نو د شپې تر ناوخته یې د کار دپاره څراغ لګېدلی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_18.mp3', '', 1761754199, 1761754199),
(51658, 'Proverbs 31:19', 'Proverbs', 31, 19, 'هغه په خپلو لاسونو څرخه کوي او په خپلو ګوتو تار له دوک نه تاووي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_19.mp3', '', 1761754199, 1761754199),
(51659, 'Proverbs 31:20', 'Proverbs', 31, 20, 'هغه غریبانو ته د مرستې لاس غزوي او د مسکینانو سره د سخاوت له مخې مرسته کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_20.mp3', '', 1761754199, 1761754199),
(51660, 'Proverbs 31:21', 'Proverbs', 31, 21, 'هغه د واورې له یخنۍ څخه وېره نه لري ځکه چې د کورنۍ ټولو غړو یې ګرم کالي اغوستي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_21.mp3', '', 1761754199, 1761754199),
(51661, 'Proverbs 31:22', 'Proverbs', 31, 22, 'هغه د خپلې بسترې دپاره پوښونه جوړوي او د بانجاني رنګه ښه کتان څخه کالي تیاروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_22.mp3', '', 1761754199, 1761754199),
(51662, 'Proverbs 31:23', 'Proverbs', 31, 23, 'د هغې مېړه د ښار په دروازو کې مشهور وي او په جرګه کې ناست مشران یې د عزت خاوند بولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_23.mp3', '', 1761754199, 1761754199),
(51663, 'Proverbs 31:24', 'Proverbs', 31, 24, 'هغه د کتان کالي او کمربندونه جوړوي او وروسته یې په سوداګرانو خرڅوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_24.mp3', '', 1761754199, 1761754199),
(51664, 'Proverbs 31:25', 'Proverbs', 31, 25, 'هغه د پت او عزت په لباس سمبال وي او د راتلونکې څخه وېره نه لري او خاندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_25.mp3', '', 1761754199, 1761754199),
(51665, 'Proverbs 31:26', 'Proverbs', 31, 26, 'هغه په حکمت سره خبرې کوي او ژبه یې له مهربانۍ نه ډکه روزنه ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_26.mp3', '', 1761754199, 1761754199),
(51666, 'Proverbs 31:27', 'Proverbs', 31, 27, 'هغه د کور په ټولو چارو پوره پاملرنه کوي او هېڅکله د لټۍ ډوډۍ نه خوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_27.mp3', '', 1761754199, 1761754199),
(51667, 'Proverbs 31:28', 'Proverbs', 31, 28, 'اولادونه یې په یوه خوله هغه مبارکه ګڼي او مېړه یې هم د هغې ستاینه کوي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_28.mp3', '', 1761754199, 1761754199),
(51668, 'Proverbs 31:29', 'Proverbs', 31, 29, '«ډېرې ښځې د پت او عزت کارونه کوي خو ته د هغو ټولو نه ښه یې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_29.mp3', '', 1761754199, 1761754199),
(51669, 'Proverbs 31:30', 'Proverbs', 31, 30, 'نازونه اداګانې غولوونکې او حسن فاني وي خو کومه ښځه چې له څښتن څخه وېریږي نو د ستاینې وړ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_30.mp3', '', 1761754199, 1761754199),
(51670, 'Proverbs 31:31', 'Proverbs', 31, 31, 'د هغې د لاسونو د کار ثمره ورکړئ او د خلکو په منځ کې یې د کار ستاینه وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs31_verse_31.mp3', '', 1761754199, 1761754199),
(51671, 'Numbers 19:1', 'Numbers', 19, 1, 'څښتن موسی او هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_1.mp3', '', 1761754199, 1761754199),
(51672, 'Numbers 19:2', 'Numbers', 19, 2, '«د اسراییلو قوم باید موسی ته یوه داسې سره غوا راولي چې کوم عیب په کې نه وي او هېڅکله ورباندې قلبه نه وي شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_2.mp3', '', 1761754199, 1761754199),
(51673, 'Numbers 19:3', 'Numbers', 19, 3, 'هغوی به هغه العازار کاهن ته ورکړي، بیا به هغه د کمپ څخه دباندې وویستل شي او د هغه په حضور کې به حلاله شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_3.mp3', '', 1761754199, 1761754199),
(51674, 'Numbers 19:4', 'Numbers', 19, 4, 'بیا به العازار د هغې څخه لږه وینه واخلي او په خپله ګوته باندې دې اووه ځلې د سپېڅلې خېمې مخې ته وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_4.mp3', '', 1761754199, 1761754199),
(51675, 'Numbers 19:5', 'Numbers', 19, 5, 'بیا ټوله غوا باید د پوستکي، غوښې، وینې او کولمو سره د هغه په مخکې وسوځول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_5.mp3', '', 1761754199, 1761754199),
(51676, 'Numbers 19:6', 'Numbers', 19, 6, 'کاهن دې د سبر د ونې لږ لرګي، د وېلني بوټی او سور تار په اور کې واچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_6.mp3', '', 1761754199, 1761754199),
(51677, 'Numbers 19:7', 'Numbers', 19, 7, 'د مراسمو څخه وروسته دې کاهن خپل کالي ووینځي او غسل دې وکړي. بیا هغه کولای شي چې بېرته کمپ ته ننوځي، خو تر ماښامه پورې به ناپاک پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_7.mp3', '', 1761754199, 1761754199),
(51678, 'Numbers 19:8', 'Numbers', 19, 8, 'هغه سړی چې غوا یې سوځولې وي هم باید خپل کالي ووینځي او غسل دې وکړي، خو هغه به هم تر ماښامه پورې ناپاک پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_8.mp3', '', 1761754199, 1761754199),
(51679, 'Numbers 19:9', 'Numbers', 19, 9, 'یو سړی چې ناپاک نه وي د سوځېدل شوې غوا ایرې دې واخلي او د کمپ څخه دباندې دې په یو پاک ځای کې واچوي. د اسراییلو قوم کولای شي چې دا ایرې د هغو اوبو سره ګډې کړي چې د ګناه د پاکولو په مراسمو کې ورڅخه کار اخیستل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_9.mp3', '', 1761754199, 1761754199),
(51680, 'Numbers 19:10', 'Numbers', 19, 10, 'هغه سړی چې ایرې راټولوي باید خپل کالي ووینځي، خو تر ماښامه پورې به ناپاک پاتې شي. د اسراییلو قوم او هغه پردي خلک چې د دوی په منځ کې اوسیږي، باید تل د دې قانون اطاعت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_10.mp3', '', 1761754199, 1761754199),
(51681, 'Numbers 19:11', 'Numbers', 19, 11, 'که چېرې څوک یو مړي ته لاس وروړي، اووه ورځې به ناپاک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_11.mp3', '', 1761754199, 1761754199),
(51682, 'Numbers 19:12', 'Numbers', 19, 12, 'خو که چېرې په درېمه ورځ او بیا په اوومه ورځ په هغو اوبو باندې چې د غوا ایرې ورسره ګډې وي خپل ځان پاک کړي، هغه به پاک شي. که په هغو ورځو کې خپل ځان پاک نه کړي، نو ناپاک به پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_12.mp3', '', 1761754199, 1761754199),
(51683, 'Numbers 19:13', 'Numbers', 19, 13, 'که چېرې څوک مړي ته لاس وروړي او خپل ځان پاک نه کړي هغه ناپاکه پاتې کیږي، ځکه چې د پاکوالي اوبه ورباندې نه دي اچول شوې. هغه کس سپېڅلې خېمه ناپاکه کړې ده او د اسراییلو د قوم څخه باید وشړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_13.mp3', '', 1761754199, 1761754199),
(51684, 'Numbers 19:14', 'Numbers', 19, 14, 'په هغه حالت کې چې یو کس په خېمه کې مړ شي، نو هغه څوک چې د هغه کس د مرګ په وخت کې په خېمه کې وي یا څوک چې خېمې ته ورننوځي هغه به اووه ورځې ناپاک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_14.mp3', '', 1761754199, 1761754199),
(51685, 'Numbers 19:15', 'Numbers', 19, 15, 'هر منګی او لوښی چې په خېمه کې وي او سرپوښ ونه لري، هغه ناپاک کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_15.mp3', '', 1761754199, 1761754199),
(51686, 'Numbers 19:16', 'Numbers', 19, 16, 'که چېرې څوک د یو داسې کس مړي ته لاس وروړي چې د کور څخه دباندې په وسله باندې وژل شوی وي یا په خپل مرګ مړ شوی وي یا که چېرې د انسان هډوکي یا قبر ته لاس وروړي، هغه به اووه ورځې ناپاک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_16.mp3', '', 1761754199, 1761754199),
(51687, 'Numbers 19:19', 'Numbers', 19, 19, 'هغه کس چې پاک وي، په ناپاکه کس باندې دې په درېمه او اوومه ورځ هغه اوبه وشیندي. په اوومه ورځ هغه کس چې پاکیږي باید خپل کالي ووینځي او غسل دې وکړي، نو ماښام به هغه پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_19.mp3', '', 1761754199, 1761754199),
(51688, 'Numbers 19:20', 'Numbers', 19, 20, 'که چېرې یو کس په مذهبي لحاظ ناپاک وي او خپل ځان پاک نه کړي هغه ناپاک پاتې کیږي، ځکه چې په هغه باندې د پاکوالي اوبه نه دي اچول شوې. هغه سپېڅلې خېمه ناپاکه کړې ده او د اسراییلو د قوم څخه باید وشړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_20.mp3', '', 1761754199, 1761754199),
(51689, 'Numbers 19:21', 'Numbers', 19, 21, 'دا قوانین به هېڅکله بدل نه شي. کوم کس چې د پاکوالي په خاطر هغه اوبه شیندي باید خپل کالي هم ووینځي. که څوک دې اوبو ته لاس وروړي هغه به تر ماښامه پورې ناپاک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_21.mp3', '', 1761754199, 1761754199),
(51690, 'Numbers 19:22', 'Numbers', 19, 22, 'یو ناپاک کس چې هر شي ته لاس وروړي هغه شی به ناپاک شي او که بل کس هغه شي ته لاس وروړي، هغه به هم تر ماښامه پورې ناپاک وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers19_verse_22.mp3', '', 1761754199, 1761754199),
(51691, 'Psalms 32:1', 'Psalms', 32, 1, 'بختور دی هغه څوک چې سرکښي یې بخښل شوې هغه څوک چې په ګناهونو یې اچول شوې پرده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms32_verse_1.mp3', '', 1761754199, 1761754199),
(51692, 'Psalms 32:2', 'Psalms', 32, 2, 'بختور دی هغه څوک چې څښتن یې نه ګڼي مجرم او هغه څوک چې د ټګۍ نه پاک وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms32_verse_2.mp3', '', 1761754199, 1761754199),
(51693, 'Psalms 32:3', 'Psalms', 32, 3, 'کله چې نه مې کاوه اقرار په ګناهونو خپلو نو ټوله ورځ به له زګېروو نه زه ستومانه ومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms32_verse_3.mp3', '', 1761754199, 1761754199),
(51694, 'Psalms 32:4', 'Psalms', 32, 4, 'راکوله به سزا راته شپه او ورځ تا ای څښتنه ما قوت خپل بیخي ورکړ له لاسه لکه څنګه چې د اوړي ګرمي وچ کړي لنده بل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms32_verse_4.mp3', '', 1761754199, 1761754199),
(51695, 'Psalms 32:5', 'Psalms', 32, 5, 'نو ما تاته اقرار وکړلو د خپلو ګناهونو پټ مې نه کړل ما له تا نه خپل جرمونه دا مې وویل د خپل ځان سره په زړه کې: «زه به په خپلو سرکښیو باندې وکړمه اقرار څښتن ته» او تا زما ټول ګناهونه معاف کړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms32_verse_5.mp3', '', 1761754199, 1761754199),
(51696, 'Psalms 32:6', 'Psalms', 32, 6, 'نو چې موقع نه وي د لاس ځینې وتلې باید ټول وفادار خلک دعا وغواړي له تا نه چې کله زیات شي تکلیفونه د سېلاب په شان تکلیف به دوی ته ور ونه رسیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms32_verse_6.mp3', '', 1761754199, 1761754199),
(51697, 'Psalms 32:7', 'Psalms', 32, 7, 'ته پناه یې زما ما به ساتې د تکلیفونو نه زما د بچ کېدو نغمې چاپېره به ویلی شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms32_verse_7.mp3', '', 1761754199, 1761754199),
(51698, 'Psalms 32:8', 'Psalms', 32, 8, 'څښتن وایي: «هغه لار به درته ښایم چې باید ته پرې لاړ شې تاته به وکړم لارښوونه زه او په تا به ساتم نظر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms32_verse_8.mp3', '', 1761754199, 1761754199),
(51699, 'Psalms 32:9', 'Psalms', 32, 9, 'بې‌عقل کېږئ مه لکه د اس او د قچر په شان چې کنترول یې په قیضه او واګي کیږي او که نه نو رابه نه شي ستاسو خواته»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms32_verse_9.mp3', '', 1761754199, 1761754199),
(51700, 'Psalms 32:10', 'Psalms', 32, 10, 'ډېر وي غمونه بدکارانو لره خو چې څوک کړي په څښتن باندې توکل ساتل کیږي به هغه د ده په تلپاتې مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms32_verse_10.mp3', '', 1761754199, 1761754199),
(51701, 'Psalms 32:11', 'Psalms', 32, 11, 'ای نېکانو، هغه څه چې څښتن کړي په هغو خوشحاله اوسئ او ښادي کړئ صادقانو، د خوښۍ ووهئ چیغې!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms32_verse_11.mp3', '', 1761754199, 1761754199),
(51702, 'Psalms 118:1', 'Psalms', 118, 1, 'د څښتن شکر کوئ، ځکه چې نېک دی هغه ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_1.mp3', '', 1761754199, 1761754199),
